function useFormDraft(key, initial) {
  const storageKey = `sw_draft_${key}`;
  const TTL = 30 * 60 * 1000; // 30 minutes

  const [state, setState] = useState(() => {
    try {
      const raw = localStorage.getItem(storageKey);
      if (!raw) return initial;
      const { value, expires } = JSON.parse(raw);
      if (Date.now() > expires) { localStorage.removeItem(storageKey); return initial; }
      return value;
    } catch { return initial; }
  });

  const setDraft = (value) => {
    const next = typeof value === "function" ? value(state) : value;
    setState(next);
    try {
      localStorage.setItem(storageKey, JSON.stringify({ value: next, expires: Date.now() + TTL }));
    } catch { /* storage full — silent fail */ }
  };

  const clearDraft = () => {
    setState(initial);
    try { localStorage.removeItem(storageKey); } catch { /* ignore */ }
  };

  return [state, setDraft, clearDraft];
}

// Search results cut titles near 60 characters and descriptions near 155, so the
// head tags are held to that here for every page, whatever the caller passes.
const SEO_TITLE_MAX = 60;
const SEO_DESC_MAX = 155;
const SEO_SITE_URL = "https://www.trysteadwell.app";
function seoClip(str, max) {
  const s = String(str || "").replace(/\s+/g, " ").trim();
  if (s.length <= max) return s;
  const cut = s.slice(0, max - 1);
  // Prefer ending on a whole sentence over a mid-sentence "…".
  let stop = -1;
  for (const m of cut.matchAll(/[.?!](?=\s)/g)) {
    if (m[0] === "." && /\b(vs|etc|approx|est|mr|mrs|ms|dr|inc|llc|e\.g|i\.e)$/i.test(cut.slice(0, m.index))) continue; // abbreviation, not a sentence end
    stop = m.index;
  }
  if (stop > max * 0.5) return cut.slice(0, stop + 1);
  if (/[.?!]$/.test(s.slice(0, max)) && s.slice(0, max).length > max * 0.5) return s.slice(0, max);
  const sp = cut.lastIndexOf(" ");
  return (sp > max * 0.6 ? cut.slice(0, sp) : cut).replace(/[\s,;:.\-—–]+$/, "") + "…";
}
function seoTitle(title) {
  const siteName = "Steadwell";
  if (!title) return `${siteName} — Home Maintenance Tracking & Asset Management`;
  const full = `${title} | ${siteName}`;
  if (full.length <= SEO_TITLE_MAX) return full;
  // Too long: prefer the part before a subtitle ("Title: subtitle", "Title (note)") over a mid-word cut.
  let lead = title.split(/:\s|\s[—–]\s|\s\(/)[0].trim();
  if (title.length > SEO_TITLE_MAX) { const q = lead.indexOf("? "); if (q > 0) lead = lead.slice(0, q + 1); } // "How long does X last? Guide to Y" -> "How long does X last?"
  if (lead.length >= 15 && lead.length < title.length) {
    if (`${lead} | ${siteName}`.length <= SEO_TITLE_MAX) return `${lead} | ${siteName}`;
    if (lead.length <= SEO_TITLE_MAX) return lead;
  }
  return seoClip(title, SEO_TITLE_MAX); // no room for the brand suffix
}

// Keeps a page out of search results (login, signup, partner pages) while mounted.
function useNoIndex(on = true) {
  useEffect(() => {
    if (!on) return undefined;
    let el = document.querySelector('meta[name="robots"]');
    const created = !el;
    if (!el) { el = document.createElement("meta"); el.setAttribute("name", "robots"); document.head.appendChild(el); }
    const prev = el.getAttribute("content");
    el.setAttribute("content", "noindex, follow");
    return () => { if (created) el.remove(); else if (prev) el.setAttribute("content", prev); };
  }, [on]);
}

function useSEO({ title, description, canonical, jsonLd, noindex, image, ogType } = {}) {
  // Build-time pre-rendering (scripts/prerender.mjs) renders each page on the server and
  // collects what it would put in <head> here; effects below never run on the server.
  if (typeof globalThis !== "undefined" && typeof globalThis.__SW_SEO_SINK__ === "function") {
    globalThis.__SW_SEO_SINK__({ title, description, canonical, jsonLd, noindex, image, ogType });
  }
  useNoIndex(!!noindex);
  useEffect(() => {
    const fullTitle = seoTitle(title);
    const metaDesc = seoClip(description || "Steadwell helps homeowners track maintenance, manage appliances, and stay ahead of repairs. Free to start.", SEO_DESC_MAX);
    const canonicalUrl = canonical || `${SEO_SITE_URL}/`;

    // Title
    document.title = fullTitle;

    // Helper to set/create meta tag
    const setMeta = (selector, attr, value) => {
      let el = document.querySelector(selector);
      if (!el) {
        el = document.createElement("meta");
        const m = selector.match(/\[(name|property)="([^"]+)"\]/);
        if (m) el.setAttribute(m[1], m[2]);
        document.head.appendChild(el);
      }
      el.setAttribute(attr, value);
    };

    setMeta('meta[name="description"]', "content", metaDesc);
    setMeta('meta[property="og:title"]', "content", fullTitle);
    setMeta('meta[property="og:description"]', "content", metaDesc);
    setMeta('meta[property="og:url"]', "content", canonicalUrl);
    setMeta('meta[name="twitter:title"]', "content", fullTitle);
    setMeta('meta[name="twitter:description"]', "content", metaDesc);
    if (ogType) setMeta('meta[property="og:type"]', "content", ogType);
    if (image) {
      setMeta('meta[property="og:image"]', "content", image);
      setMeta('meta[name="twitter:image"]', "content", image);
    }

    // Canonical
    let canonEl = document.querySelector('link[rel="canonical"]');
    if (!canonEl) { canonEl = document.createElement("link"); canonEl.setAttribute("rel","canonical"); document.head.appendChild(canonEl); }
    canonEl.setAttribute("href", canonicalUrl);

    // JSON-LD
    const existingLd = document.querySelector('script[data-seo="dynamic"]');
    if (existingLd) existingLd.remove();
    if (jsonLd) {
      const script = document.createElement("script");
      script.type = "application/ld+json";
      script.setAttribute("data-seo","dynamic");
      script.textContent = JSON.stringify(jsonLd);
      document.head.appendChild(script);
    }

    return () => {
      // Reset to defaults on unmount
      document.title = seoTitle("");
      const ld = document.querySelector('script[data-seo="dynamic"]');
      if (ld) ld.remove();
    };
  }, [title, description, canonical, image, ogType, JSON.stringify(jsonLd)]);
}

