function AffiliateAgreementPage() {
  const seoPath = "/affiliate-agreement";
  const seoDesc = "Steadwell affiliate program terms — commission rates, cookie window, payout schedule, and prohibited promotion methods.";
  useSEO({
    title:"Affiliate Agreement",
    description:seoDesc,
    canonical:`https://www.trysteadwell.app${seoPath}`,
    jsonLd: lpPageJsonLd({ name:"Affiliate Agreement", path:seoPath, description:seoDesc }),
  });

  const S = {
    wrap:  { maxWidth:720, margin:"0 auto", padding:"48px 24px 80px" },
    h1:    { fontFamily:"'Fraunces',serif", fontWeight:500, fontSize:"clamp(1.8rem,4vw,2.4rem)", color:"#234A3D", letterSpacing:"-.02em", marginBottom:8 },
    meta:  { fontSize:".82rem", color:"#A8A09A", marginBottom:40 },
    h2:    { fontFamily:"'Fraunces',serif", fontWeight:500, fontSize:"1.2rem", color:"#234A3D", margin:"36px 0 10px" },
    p:     { fontSize:".95rem", color:"#5A534B", lineHeight:1.75, marginBottom:14 },
    li:    { fontSize:".93rem", color:"#5A534B", lineHeight:1.7, marginBottom:8 },
  };

  const sections = [
    {t:"1. Parties",b:"This Affiliate Agreement (the &quot;Agreement&quot;) is between Steadwell, LLC, a Florida limited liability company (&quot;Steadwell&quot;, &quot;we&quot;, &quot;us&quot;) and the individual or entity that completes the affiliate application (&quot;Affiliate&quot;, &quot;you&quot;). By submitting an application and participating in the Steadwell Affiliate Program (the &quot;Program&quot;), you agree to be bound by this Agreement."},
    {t:"2. Program Overview",b:"The Program allows approved Affiliates to earn commissions by referring new paying customers to Steadwell's subscription plans and digital product store. Referrals are tracked via a unique affiliate link assigned to each Affiliate upon approval."},
    {t:"3. Application and Approval",b:"Participation in the Program requires prior written approval from Steadwell. We review applications within 3 business days. We reserve the right to approve or reject any application at our sole discretion, without obligation to provide a reason. Approval may be revoked at any time for violation of this Agreement or for any other reason."},
    {t:"4. Commission Structure",b:"Approved Affiliates earn the following commissions on net revenue (after Stripe processing fees): Plus Plan ($7.99/month) — 30% recurring for up to 12 months per referred subscriber. Plus Plan annual ($63.99/year) — 40% one-time commission (~$25.60) paid the following month. Pro Plan ($14.99/month) — 30% recurring for up to 12 months per referred subscriber. Pro Plan annual ($119.99/year) — 40% one-time commission (~$48.00) paid the following month. PDF Guides — 25% of the net sale price per completed purchase. Commissions are calculated on confirmed, non-refunded revenue only. If a referred subscriber cancels or requests a refund, any associated unpaid commission is forfeited."},
    {t:"5. Cookie Window and Attribution",b:"A 30-day tracking cookie is set when a user clicks your affiliate link. If that user completes a paid subscription or purchase within 30 days of clicking your link, you receive credit for the referral. Last-click attribution applies — if a user clicks multiple affiliate links, the most recent click receives the commission."},
    {t:"6. Payouts",b:"Commissions are paid monthly via PayPal or bank transfer. Payments are issued within 15 days of the end of each calendar month for commissions earned in the prior month. A minimum balance of $50.00 USD is required before a payout is issued. Balances below $50.00 roll over to the following month. You are responsible for any taxes, duties, or fees associated with commission income. Steadwell will issue a 1099-NEC to US-based affiliates whose annual earnings exceed $600."},
    {t:"7. Prohibited Conduct",b:"You may not: (a) bid on Steadwell-branded keywords (including 'Steadwell', 'trysteadwell', or any variation) in paid search advertising without prior written approval; (b) create websites, social accounts, or email addresses that impersonate Steadwell or could be confused with official Steadwell accounts; (c) use spam, unsolicited email, or deceptive marketing practices to promote Steadwell; (d) make false or misleading claims about Steadwell's features, pricing, or results; (e) offer cash rebates, unauthorized discounts, or incentives to referred users; (f) self-refer — you may not use your own affiliate link to create a paid Steadwell account for yourself; (g) promote Steadwell through content that violates any applicable law or our Terms of Service; (h) solicit, write, or publish fake, incentivized-without-disclosure, or otherwise deceptive reviews or testimonials about Steadwell; (i) state or imply a specific dollar or income amount that you or any affiliate has earned or can expect to earn through the Program beyond the commission percentages disclosed in Section 4."},
    {t:"8. FTC Disclosure Requirements and Compliance Monitoring",b:"Under the FTC's Endorsement Guides (16 CFR Part 255), you must clearly and conspicuously disclose your material connection to Steadwell — that you earn a commission — in close proximity to any recommendation, review, post, video, or other content promoting Steadwell, in language a reasonable person would notice (for example, \"I earn a commission if you sign up through this link,\" or a clearly visible #ad/#sponsored tag — not buried in a bio or a long list of hashtags). This requirement applies in addition to, not in place of, the restrictions in Section 7. Steadwell may monitor, audit, and request evidence of your promotional content and disclosure practices at any time, require corrective action, and withhold or claw back commissions and terminate this Agreement for noncompliance with this Section, in addition to any other remedy available under Section 11."},
    {t:"9. Content and Brand Guidelines",b:"You may use Steadwell's name, logo, and approved marketing materials solely for the purpose of promoting the Program in accordance with this Agreement. We reserve the right to request removal of any content that misrepresents the product, uses outdated materials, or violates our brand guidelines. Steadwell-provided creative assets are provided for affiliate use only and may not be sublicensed or resold."},
    {t:"10. Relationship of Parties",b:"You are an independent contractor, not an employee, partner, or agent of Steadwell. You have no authority to make commitments on behalf of Steadwell or to bind Steadwell in any way. You are responsible for your own taxes, insurance, and business expenses."},
    {t:"11. Modification and Termination",b:"Steadwell may modify the commission structure, cookie window, or other Program terms at any time with 30 days written notice to active affiliates. Changes to prohibited conduct provisions may take effect immediately. Either party may terminate this Agreement at any time with written notice. Upon termination, unpaid commissions for confirmed, non-refunded referrals made prior to the termination date will be paid at the next regular payout date."},
    {t:"12. Disclaimers and Limitation of Liability",b:"THE PROGRAM IS PROVIDED AS IS. STEADWELL MAKES NO WARRANTIES ABOUT COMMISSION EARNINGS, CONVERSION RATES, OR THE CONTINUED AVAILABILITY OF THE PROGRAM. TO THE FULLEST EXTENT PERMITTED BY LAW, STEADWELL'S LIABILITY TO ANY AFFILIATE SHALL NOT EXCEED THE TOTAL COMMISSIONS PAID TO THAT AFFILIATE IN THE 3 MONTHS PRECEDING THE CLAIM."},
    {t:"13. Governing Law",b:"This Agreement is governed by the laws of the State of Florida. Any disputes arising from this Agreement shall be resolved in the state or federal courts located in Pinellas County, Florida."},
    {t:"14. Contact",b:"Affiliate program questions: affiliates@trysteadwell.app · Steadwell, LLC · 7901 4th Street N. Suite 36148, St. Petersburg, FL 33702 · 727-658-4491"},
  ];

  return (
    <div style={{minHeight:"100vh",background:"#F4EDDF",fontFamily:"'Hanken Grotesk',sans-serif"}}>
      <LPNav links={[{href:"/affiliates",label:"Affiliate Program"},{href:"/terms",label:"Terms"},{href:"/privacy",label:"Privacy"}]}/>
      <div style={S.wrap}>
        <h1 style={S.h1}>Affiliate Agreement</h1>
        <p style={S.meta}>Effective date: July 9, 2026 &nbsp;&middot;&nbsp; Steadwell, LLC</p>
        {sections.map((s,i)=>(
          <div key={i}>
            <h2 style={S.h2}>{s.t}</h2>
            <p style={S.p}>{s.b}</p>
          </div>
        ))}
      </div>
      <footer style={{background:"#234A3D",padding:"28px 24px",display:"flex",justifyContent:"space-between",flexWrap:"wrap",gap:12,fontSize:".82rem"}}>
        <span style={{color:"rgba(244,237,223,.5)"}}>© 2026 Steadwell, LLC. All rights reserved.</span>
        <div style={{display:"flex",gap:20}}>
          <a href="/affiliates" style={{color:"rgba(244,237,223,.55)",textDecoration:"none"}}>Affiliate Program</a>
          <a href="/terms" style={{color:"rgba(244,237,223,.55)",textDecoration:"none"}}>Terms</a>
          <a href="/privacy" style={{color:"rgba(244,237,223,.55)",textDecoration:"none"}}>Privacy</a>
        </div>
      </footer>
    </div>
  );
}

