// schema.org graph for a feature page. FAQ entries are the same strings the page
// renders, so structured data always matches the visible content.
function lpJsonLd({ name, path, description, features = [], faq = [], offers = [] }) {
  const url = `https://www.trysteadwell.app${path}`;
  const graph = [
    {
      "@type": "SoftwareApplication",
      "name": name,
      "url": url,
      "description": description,
      "applicationCategory": "HomeAndGarden",
      "operatingSystem": "Web",
      "featureList": features,
      "offers": offers.map(o => ({ "@type": "Offer", "name": o.name, "price": o.price, "priceCurrency": "USD" })),
      "publisher": { "@type": "Organization", "name": "Steadwell", "url": "https://www.trysteadwell.app" },
    },
    {
      "@type": "BreadcrumbList",
      "itemListElement": [
        { "@type": "ListItem", "position": 1, "name": "Steadwell", "item": "https://www.trysteadwell.app/" },
        { "@type": "ListItem", "position": 2, "name": name, "item": url },
      ],
    },
  ];
  if (faq.length) {
    graph.push({
      "@type": "FAQPage",
      "mainEntity": faq.map(([q, a]) => ({ "@type": "Question", "name": q, "acceptedAnswer": { "@type": "Answer", "text": a } })),
    });
  }
  return { "@context": "https://schema.org", "@graph": graph };
}

// schema.org graph for plain content pages (legal, policy and partner pages): a WebPage plus breadcrumbs,
// and the page's own FAQ when it shows one.
function lpPageJsonLd({ name, path, description, faq = [] }) {
  const url = `https://www.trysteadwell.app${path}`;
  const graph = [
    {
      "@type": "WebPage",
      "name": name,
      "url": url,
      "description": description,
      "isPartOf": { "@type": "WebSite", "name": "Steadwell", "url": "https://www.trysteadwell.app/" },
      "publisher": { "@type": "Organization", "name": "Steadwell", "url": "https://www.trysteadwell.app" },
    },
    {
      "@type": "BreadcrumbList",
      "itemListElement": [
        { "@type": "ListItem", "position": 1, "name": "Steadwell", "item": "https://www.trysteadwell.app/" },
        { "@type": "ListItem", "position": 2, "name": name, "item": url },
      ],
    },
  ];
  if (faq.length) {
    graph.push({
      "@type": "FAQPage",
      "mainEntity": faq.map(([q, a]) => ({ "@type": "Question", "name": q, "acceptedAnswer": { "@type": "Answer", "text": a } })),
    });
  }
  return { "@context": "https://schema.org", "@graph": graph };
}

// A feature card with a badge and a checked field list (same look as the existing pages).
function LPFieldCard({ icon, title, badge, desc, fields = [], link }) {
  return (
    <LPCard>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:8,marginBottom:12}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          <span style={{fontSize:"1.3rem"}} aria-hidden="true">{icon}</span>
          <h3 style={{fontWeight:700,fontSize:".95rem",color:"#234A3D",margin:0}}>{title}</h3>
        </div>
        {badge && <span style={{background:"rgba(35,74,61,.08)",color:"#234A3D",fontSize:".62rem",fontWeight:700,padding:"2px 8px",borderRadius:6,flexShrink:0}}>{badge}</span>}
      </div>
      {desc && <div style={{fontSize:".82rem",color:"#7A7370",marginBottom:12,lineHeight:1.55}}>{desc}</div>}
      {fields.map((f,j)=>(
        <div key={j} style={{display:"flex",alignItems:"flex-start",gap:8,marginBottom:7,fontSize:".82rem",color:"#5E574F",textAlign:"left"}}>
          <span style={{color:"#234A3D",fontWeight:700,fontSize:".7rem",flexShrink:0,marginTop:3}}>✓</span><span style={{flex:1}}>{f}</span>
        </div>
      ))}
      {link && <a href={link.href} style={{display:"inline-block",marginTop:6,fontSize:".82rem",fontWeight:700,color:"#C16140",textDecoration:"none"}}>{link.label} →</a>}
    </LPCard>
  );
}

// Plan tiles (same look as the pricing tiles on the Warranty Tracker page) with an
// included-features list. plans: [{plan, price, period, annual, desc, features, cta, popular}]
function LPPlanTiles({ plans = [], maxWidth }) {
  return (
    <>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(min(100%,230px),1fr))",gap:16,maxWidth:maxWidth||"none",margin:"0 auto"}}>
        {plans.map((p,i)=>(
          <LPCard key={i} style={{display:"flex",flexDirection:"column",padding:"22px 22px 20px",border:p.popular?"2px solid #C16140":"1px solid #E6DECF"}}>
            <div style={{fontSize:".62rem",fontWeight:700,color:"#C16140",textTransform:"uppercase",letterSpacing:".05em",marginBottom:8,minHeight:12,visibility:p.popular?"visible":"hidden"}}>Most popular</div>
            <h3 style={{fontWeight:700,fontSize:"1rem",color:"#234A3D",margin:"0 0 4px"}}>{p.plan}</h3>
            <div style={{fontSize:"1.6rem",fontWeight:700,marginBottom:2,color:"#2A2723"}}>{p.price}<span style={{fontSize:".78rem",fontWeight:500,color:"#7A7370"}}>{p.period}</span></div>
            <div style={{fontSize:".78rem",color:"#7A7370",marginBottom:10,minHeight:16,visibility:p.annual?"visible":"hidden"}}>{p.annual || "placeholder"}</div>
            {p.desc && <div style={{fontSize:".84rem",color:"#5E574F",lineHeight:1.5,marginBottom:14,paddingBottom:14,borderBottom:"1px solid #E6DECF"}}>{p.desc}</div>}
            <div style={{flex:1,marginBottom:18}}>
              {(p.features||[]).map((f,j)=>(
                <div key={j} style={{display:"flex",alignItems:"flex-start",gap:8,marginBottom:8,fontSize:".84rem",color:"#2A2723",lineHeight:1.45,textAlign:"left"}}>
                  <span style={{color:"#2E7050",fontWeight:700,fontSize:".72rem",flexShrink:0,marginTop:3}} aria-hidden="true">✓</span><span style={{flex:1}}>{f}</span>
                </div>
              ))}
            </div>
            <a href="/?action=signup" style={{display:"block",textAlign:"center",background:p.popular?"#C16140":"transparent",color:p.popular?"#fff":"#234A3D",border:p.popular?"2px solid #C16140":"1.5px solid #234A3D",textDecoration:"none",padding:".62rem 1rem",borderRadius:9,fontWeight:700,fontSize:".85rem"}}>{p.cta}</a>
          </LPCard>
        ))}
      </div>
      <p style={{fontSize:".78rem",color:"#A8A09A",marginTop:16}}>Paid plans auto-renew until cancelled. See our <a href="/terms" style={{color:"#C16140"}}>Terms of Service</a> for full billing details.</p>
    </>
  );
}

// "Keep going" strip: internal links to sibling feature pages, followed by the
// guides that support this page (matched by keyword against the live blog list).
function LPGuides({ path }) {
  const { posts } = useBlogPosts();
  const guides = guidesForPage(path, posts, 3);
  if (!guides.length) return null;
  return (
    <LPSection>
      <LPSectionHead h2="Guides that go deeper" sub="Plain-English articles that pair with this page."/>
      <LPGrid cols="repeat(auto-fit,minmax(240px,1fr))" gap={14}>
        {guides.map(g => (
          <a key={g.slug} href={`/blog/${g.slug}`} style={{textDecoration:"none",color:"inherit"}}>
            <LPCard style={{height:"100%"}}>
              {g.tag && <div style={{fontSize:".66rem",fontWeight:700,color:"#C16140",marginBottom:6}}>{g.tag}</div>}
              <div style={{fontFamily:"'Fraunces',serif",fontWeight:500,fontSize:"1rem",color:"#234A3D",marginBottom:6,lineHeight:1.3}}>{g.title}</div>
              <div style={{fontSize:".82rem",color:"#7A7370",lineHeight:1.5}}>{g.description}</div>
            </LPCard>
          </a>
        ))}
      </LPGrid>
    </LPSection>
  );
}

function LPRelated({ hrefs = [], heading = "More ways Steadwell keeps your home on track" }) {
  const items = hrefs.map(h => LP_FEATURE_PAGES.find(p => p.href === h)).filter(Boolean);
  const path = typeof window !== "undefined" ? (window.location.pathname.replace(/\/+$/, "") || "/") : (globalThis.__SW_PATH__ || "/");
  return (
    <>
      <LPGuides path={path}/>
      <LPSection alt>
        <LPSectionHead h2={heading}/>
        <LPGrid cols="repeat(auto-fit,minmax(220px,1fr))" gap={14}>
          {items.map(p => (
            <a key={p.href} href={p.href} style={{textDecoration:"none",color:"inherit"}}>
              <LPCard style={{height:"100%"}}>
                <div style={{fontSize:"1.4rem",marginBottom:8}} aria-hidden="true">{p.icon}</div>
                <div style={{fontWeight:700,fontSize:".95rem",color:"#234A3D",marginBottom:4}}>{p.label}</div>
                <div style={{fontSize:".82rem",color:"#7A7370",lineHeight:1.5}}>{p.desc}</div>
              </LPCard>
            </a>
          ))}
        </LPGrid>
      </LPSection>
    </>
  );
}

